const cash = $('GET Cash Balance').item.json.free || 0;
const positions = $input.all().map(i => {
  const p = i.json;
  const invested = (p.averagePrice || 0) * (p.quantity || 0);
  const currentValue = p.currentPrice ? (p.currentPrice * p.quantity) : invested;
  const pnl = p.ppl !== undefined ? p.ppl : (currentValue - invested);
  const pnlPct = invested > 0 ? parseFloat(((pnl / invested) * 100).toFixed(2)) : 0;
  return {
    ticker: p.ticker,
    quantity: p.quantity,
    averagePrice: p.averagePrice,
    currentPrice: p.currentPrice,
    currentValue: parseFloat(currentValue.toFixed(2)),
    pnl: parseFloat(pnl.toFixed(2)),
    pnlPct
  };
});
return [{json: {cash: parseFloat(cash.toFixed(2)), positions}}];

const tradeHistory = $('Read Trade Log').item.json.stdout || 'No trade history available';
const portfolio = $('Store Portfolio').item.json;
const dipResponse = $input.all()[0].json;
const dipItem = Array.isArray(dipResponse) ? dipResponse[0] : dipResponse;
const dipContext = dipItem.answer || (dipItem.results || []).slice(0,3).map(x => x.content).join(' ') || 'No dip data available';
const positions = portfolio.positions || [];
const cash = portfolio.cash || 0;
const totalPnl = positions.reduce((s,p) => s + (p.pnl||0), 0).toFixed(2);

const systemPrompt = `You are a portfolio manager for a UK Stocks & Shares ISA targeting 8% annual growth.`;

const userPrompt = `CURRENT PORTFOLIO:
${JSON.stringify(positions, null, 2)}

ACCOUNT SUMMARY:
- Free cash available: £${cash}
- Total P&L: £${totalPnl}

DIP OPPORTUNITIES (live market research):
${dipContext}

TASK: Review the portfolio and recommend:
1. Which positions to SELL based on these rules:
   - Down 15%+ AND still trending down = SELL, cut the loss
   - Down 10-14% AND a better dip opportunity exists = SWAP out, rotate into the dip
   - Up 10%+ AND momentum slowing OR analyst outlook weakening = TAKE PROFIT, rotate into dip
   - Up 10%+ AND still strong momentum = HOLD, let it run
   - NEVER sell positions worth less than £10
2. What to BUY with proceeds + free cash:
   - First priority: dip opportunities from the research above (strong fundamentals, temporary drop)
   - Second priority: rebalance toward underweight targets
   - Only recommend buys if free cash > £10 OR sells will generate cash
   - If nothing to sell AND cash < £10 AND no compelling dips = set noAction to true

IMPORTANT:
- Only sell positions you are CERTAIN exist in the portfolio above
- For buys use ONLY T212 ticker format: UK ETFs like VUSAl_EQ, ISFl_EQ, SWLDl_EQ, VFEMl_EQ, VERXl_EQ, EQQQl_EQ. US stocks like AAPL_US_EQ, NVDA_US_EQ, PLTR_US_EQ
- Buy amounts must reflect ACTUAL available cash (free cash + proceeds from sells)
- amount must be a NUMBER
- Spread buys across 2-4 instruments max
- Set isDip:true on any buy that is a dip opportunity

Return ONLY valid JSON:
{"sells":[{"ticker":"WEAK_EQ","reason":"Down 15% with poor fundamentals"}],"buys":[{"ticker":"VUSAl_EQ","amount":50.00,"reason":"Strong S&P momentum","isDip":false}],"summary":"Brief rebalance strategy","noAction":false}`;

return [{json: {cash, dipContext, systemPrompt, userPrompt}}];

const raw = $input.item.json.content || $input.item.json.message?.content || $input.item.json.response || '';
const portfolio = $('Store Portfolio').item.json;

let parsed;
try {
  parsed = JSON.parse(raw.replace(/```json/g,'').replace(/```/g,'').trim());
} catch(e) {
  const match = raw.match(/\{[\s\S]*\}/);
  if (match) { parsed = JSON.parse(match[0]); }
  else { throw new Error('Could not parse Ollama response: ' + raw.substring(0,300)); }
}

const sells = (parsed.sells || []).map(s => {
  const pos = portfolio.positions.find(p => p.ticker === s.ticker);
  return {ticker: s.ticker, quantity: pos ? pos.quantity : 0, currentValue: pos ? pos.currentValue : 0, reason: s.reason};
}).filter(s => s.quantity > 0.0001 && s.currentValue >= 10);

const buys = (parsed.buys || []).filter(b => b.ticker && typeof b.amount === 'number' && b.amount >= 5);
const noAction = parsed.noAction || (sells.length === 0 && buys.length === 0 && portfolio.cash < 10);

return [{json: {sells, buys, summary: parsed.summary || 'Weekly rebalance', noAction, freeCash: portfolio.cash, sellCount: sells.length, buyCount: buys.length}}];

const cash = $input.item.json.free || 0;
const plan = $('Parse Rebalance Plan').item.json;

if (cash < 5) {
  return [{json: {buys: [], totalCash: cash, skipped: true}}];
}

const buys = plan.buys || [];
if (buys.length === 0) {
  return [{json: {buys: [], totalCash: parseFloat(cash.toFixed(2))}}];
}

const totalPlanned = buys.reduce((s, b) => s + b.amount, 0);
const adjusted = buys.map(b => ({
  ticker: b.ticker,
  amount: parseFloat(((b.amount / totalPlanned) * cash).toFixed(2)),
  reason: b.reason,
  isDip: b.isDip || false
})).filter(b => b.amount >= 5);

return [{json: {buys: adjusted, totalCash: parseFloat(cash.toFixed(2))}}];

const ticker = $json.ticker;
const amount = $json.amount;
const reason = $json.reason;
const isDip = $json.isDip || false;
let yahooSymbol;
if (ticker.includes('_US_EQ')) {
  yahooSymbol = ticker.replace('_US_EQ', '');
} else {
  yahooSymbol = ticker.replace(/[a-z]*_EQ$/, '') + '.L';
}
return [{json: {ticker, amount, reason, isDip, yahooSymbol}}];

const data = $input.item.json;
const ticker = $('Map Ticker to Yahoo').item.json.ticker;
const amount = $('Map Ticker to Yahoo').item.json.amount;
const reason = $('Map Ticker to Yahoo').item.json.reason;
const isDip = $('Map Ticker to Yahoo').item.json.isDip;
const result = data.chart?.result?.[0];
const price = result?.meta?.regularMarketPrice || result?.meta?.previousClose;
if (!price || price <= 0) {
  throw new Error('No price for ' + ticker);
}
const finalQty = Math.round((amount / price) * 100) / 100;
return [{json: {ticker, amount, reason, isDip, price, quantity: Math.max(finalQty, 0.01)}}];

const items = $input.all();
const plan = $('Parse Rebalance Plan').item.json;
const calcItems = $('Calculate Quantity').all();
const lines = calcItems.map(i => {
  const q = i.json;
  const dipLabel = q.isDip ? '🎯 DIP BUY' : '📈 Rebalance';
  return dipLabel + ' ' + q.ticker + ': ' + q.quantity + ' shares @ £' + (q.price ? q.price.toFixed(2) : '?') + ' (£' + q.amount + ') — ' + q.reason;
}).join('\n');
return [{json: {summary: plan.summary, buySummary: lines || 'Trades executed'}}];
